package org.thymeleaf.spring5.view;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.Collections;
import java.util.Locale;

import javax.servlet.ServletContext;

import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import org.springframework.mock.web.MockServletContext;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.web.context.support.StaticWebApplicationContext;
import org.thymeleaf.spring5.SpringTemplateEngine;
import org.thymeleaf.templateresolver.StringTemplateResolver;

class ThymeleafViewRenderFragmentTests {

    @Test
    void renderWritesRenderedTemplateAndAppliesResponseSettings() throws Exception {
        final ServletContext servletContext = new MockServletContext();

        final StaticWebApplicationContext applicationContext =
                new StaticWebApplicationContext();
        applicationContext.setServletContext(servletContext);
        applicationContext.refresh();
        servletContext.setAttribute(
                WebApplicationContext.ROOT_WEB_APPLICATION_CONTEXT_ATTRIBUTE,
                applicationContext);

        final StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setCacheable(false);

        final SpringTemplateEngine templateEngine = new SpringTemplateEngine();
        templateEngine.setTemplateResolver(resolver);

        final ThymeleafView view = new ThymeleafView("Hello [[${name}]]");
        view.setServletContext(servletContext);
        view.setApplicationContext(applicationContext);
        view.setTemplateEngine(templateEngine);
        view.setLocale(Locale.CANADA);
        view.setForceContentType(true);
        view.setContentType("text/plain");
        view.setCharacterEncoding("UTF-8");
        view.setProducePartialOutputWhileProcessing(false);

        final MockHttpServletRequest request = new MockHttpServletRequest(servletContext);
        final MockHttpServletResponse response = new MockHttpServletResponse();

        view.render(Collections.singletonMap("name", "Ada"), request, response);

        assertEquals("Hello Ada", response.getContentAsString());
        assertEquals(Locale.CANADA, response.getLocale());
        assertEquals("UTF-8", response.getCharacterEncoding());
        assertNotNull(response.getContentType());
        assertEquals("text/plain;charset=UTF-8", response.getContentType());
    }

    @Test
    void renderRejectsViewWithoutTemplateName() {
        final ServletContext servletContext = new MockServletContext();

        final StaticWebApplicationContext applicationContext =
                new StaticWebApplicationContext();
        applicationContext.setServletContext(servletContext);
        applicationContext.refresh();
        servletContext.setAttribute(
                WebApplicationContext.ROOT_WEB_APPLICATION_CONTEXT_ATTRIBUTE,
                applicationContext);

        final ThymeleafView view = new ThymeleafView();
        view.setServletContext(servletContext);
        view.setApplicationContext(applicationContext);
        view.setLocale(Locale.US);

        final MockHttpServletRequest request =
                new MockHttpServletRequest(servletContext);
        final MockHttpServletResponse response = new MockHttpServletResponse();

        final IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> view.render(Collections.emptyMap(), request, response));

        assertEquals("Property 'templateName' is required", exception.getMessage());
    }
}

