import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.Context;
import org.thymeleaf.templateresolver.StringTemplateResolver;
import org.thymeleaf.templatemode.TemplateMode;

class ProcessorTemplateHandlerHandleStandaloneElementTests {

    @Test
    void processesStandaloneElementIterationAndAppliesAttributesToEachGeneratedElement() {
        StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode(TemplateMode.HTML);

        TemplateEngine templateEngine = new TemplateEngine();
        templateEngine.setTemplateResolver(resolver);

        Context context = new Context(Locale.ENGLISH);
        context.setVariable("items", Arrays.asList("first", "second"));

        String result = templateEngine.process(
                "<meta th:each=\"item : ${items}\" th:attr=\"data-value=${item}\" />",
                context);

        assertTrue(result.contains("data-value=\"first\""));
        assertTrue(result.contains("data-value=\"second\""));
        assertEquals(2, countOccurrences(result, "data-value="));
    }

    private static int countOccurrences(String value, String searched) {
        int count = 0;
        int index = 0;
        while ((index = value.indexOf(searched, index)) >= 0) {
            count++;
            index += searched.length();
        }
        return count;
    }
}

