    void insertsAnEmptyLiteralBetweenAdjacentExpressions() {
        String input = "|${first}${second}|";

        assertEquals("${first} + '' + ${second}",
                LiteralSubstitutionUtil.performLiteralSubstitution(input));
    }
}

